"""Azure ASR engine — configuration model."""

from typing import Optional

from pydantic import model_validator

from rasa.core.channels.voice_stream.asr.asr_engine import (
    ASRConfigError,
    ASREngineConfig,
)


class AzureASRConfig(ASREngineConfig):
    """Configuration for Azure ASR.

    Attributes:
        speech_region: Azure speech service region.
        speech_host: Custom host URL.
        speech_endpoint: Custom endpoint URL.
    """

    speech_region: Optional[str] = None
    speech_host: Optional[str] = None
    speech_endpoint: Optional[str] = None

    @model_validator(mode="after")
    def _validate_language_map_has_language(self) -> "AzureASRConfig":
        """Enforce that every language_map entry specifies a language code.

        Azure requires an explicit language code (e.g. 'en-US') for each
        entry;

        Raises:
            ASRConfigError: When any language_map entry is missing a language.
        """
        for rasa_lang, entry in (self.language_map or {}).items():
            if not entry.language:
                raise ASRConfigError(
                    f"Azure ASR language_map entry for '{rasa_lang}' is missing "
                    f"a 'language' value (e.g. 'en-US'). Azure requires an explicit "
                    f"language code for each entry."
                )
        return self
